async () => {
  const img = new Image(); img.src = 'photo.png'; await img.decode();
  const c = document.createElement('canvas'); c.width = img.width; c.height = img.height;
  const x = c.getContext('2d'); x.drawImage(img,0,0);
  const d = x.getImageData(0,0,img.width,img.height).data;
  let sunTop=-1,sunBot=-1,greenTop=-1;
  for (let y=0;y<img.height;y++){
    let sun=false,green=false;
    for (let px=0;px<img.width;px+=4){
      const i=(y*img.width+px)*4, r=d[i],g=d[i+1],b=d[i+2];
      if (r>200&&g>170&&b<130) sun=true;
      if (g>90&&g>r+30&&g>b+30) green=true;
    }
    if(sun){ if(sunTop<0) sunTop=y; sunBot=y; }
    if(green&&greenTop<0) greenTop=y;
  }
  return JSON.stringify({w:img.width,h:img.height,sunTop,sunBot,greenTop,
    sunTopF:+(sunTop/img.height).toFixed(3), sunBotF:+(sunBot/img.height).toFixed(3), greenTopF:+(greenTop/img.height).toFixed(3)});
}

